package com.danawa.search.analysis.product.action

import org.elasticsearch.action.support.nodes.BaseNodesRequest

/**
 * 클러스터 전체 노드에 대한 사전 리로드 요청
 * ES 9.1.2: BaseNodesRequest (raw type) 상속
 */
class ReloadDictNodesRequest : BaseNodesRequest<ReloadDictNodesRequest> {

    var dictionaryType: String? = null

    /**
     * 기본 생성자 - 모든 노드 대상
     */
    constructor() : super(*arrayOfNulls<String>(0))

    /**
     * 사전 타입 지정 생성자
     */
    constructor(dictionaryType: String?) : super(*arrayOfNulls<String>(0)) {
        this.dictionaryType = dictionaryType
    }
}
